'}'); }\\n  /** Prints a key (string + colon + space) **/\\n  simdjson_inline void key(std::string_view unescaped) {\\n    string(unescaped);\\n    one_char(':');\\n    one_char(' ');\\n  }\\n  /** Clears out the content. **/\\n  simdjson_inline void clear() { mini_formatter::clear(); depth = 0; }\\nprivate:\\n  /** Ends a container, handling the empty-container case **/\\n  simdjson_inline void close_container(char c) {\\n    depth--;\\n    if (buffer.back() == char(c - 2)) { // the container was empty: print [] or {}\\n      one_char(c);\\n    } else {\\n      one_char('\\\\n');\\n      print_indent();\\n      one_char(c);\\n    }\\n  }\\n  /** Prints four spaces per nesting level **/\\n  simdjson_inline void print_indent() {\\n    for (size_t i = 0; i < depth; i++) {\\n      one_char(' '); one_char(' '); one_char(' '); one_char(' ');\\n    }\\n  }\\n  size_t depth{0};\\n};\\n\\n} // internal\"}, {\"path\": \"include/simdjson/dom/serialization.h\", \"source_sha256\": \"0b6b017b3f503415c7104d648d9e632f1c06e6d226272fd600cabcb3a2c55fdb\", \"old_text\": \"#if SIMDJSON_EXCEPTIONS\\ntemplate <class T>\\nstd::string minify(simdjson_result<T> x) {\\n    if (x.error()) { throw simdjson_error(x.error()); }\\n    return to_string(x.value());\\n}\\n#endif\\n\\n\\n} // namespace simdjson\", \"new_text\": \"#if SIMDJSON_EXCEPTIONS\\ntemplate <class T>\\nstd::string minify(simdjson_result<T> x) {\\n    if (x.error()) { throw simdjson_error(x.error()); }\\n    return to_string(x.value());\\n}\\n#endif\\n\\n/**\\n * Prettifies a JSON element or document, printing the JSON in a\\n * human-readable form: one value per line, indented with four spaces\\n * per nesting level.\\n *\\n *   dom::parser parser;\\n *   element doc = parser.parse(\\\"   [ 1 , 2 , 3 ] \\\"_padded);\\n *   cout << prettify(doc) << endl;\\n *   // prints:\\n *   // [\\n *   //     1,\\n *   //     2,\\n *   //     3\\n *   // ]\\n *\\n */\\ntemplate <class T>\\nstd::string prettify(T x)  {\\n    simdjson::internal::string_builder<simdjson::internal::simdjson_prettify_formatter> sb;\\n    sb.append(x);\\n    std::string_view answer = sb.str();\\n    return std::string(answer.data(), answer.size());\\n}\\n#if SIMDJSON_EXCEPTIONS\\ntemplate <class T>\\nstd::string prettify(simdjson_result<T> x) {\\n    if (x.error()) { throw simdjson_error(x.error()); }\\n    return prettify(x.value());\\n}\\n#endif\\n\\n\\n} // namespace simdjson\"}]}"}}]}}]}

